import{_ as s,o as e,c as i,a0 as t}from"./chunks/framework.DCluYYrN.js";const k=JSON.parse('{"title":"模块 WebUI","description":"","frontmatter":{},"headers":[],"relativePath":"zh_CN/guide/module-webui.md","filePath":"zh_CN/guide/module-webui.md"}'),n={name:"zh_CN/guide/module-webui.md"};function p(l,a,r,h,o,c){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="模块-webui" tabindex="-1">模块 WebUI <a class="header-anchor" href="#模块-webui" aria-label="Permalink to &quot;模块 WebUI&quot;">​</a></h1><p>KernelSU 的模块除了执行启动脚本和修改系统文件之外，还支持显示 UI 界面和与用户交互。</p><p>你可以通过任何 Web 技术编写 HTML + CSS + JavaScript 页面，KernelSU 的管理器将通过 WebView 显示这些页面。此外，KernelSU 还提供了一些用于与系统交互的 JavaScript API，例如执行 shell 命令。</p><h2 id="webui-根目录" tabindex="-1">WebUI 根目录 <a class="header-anchor" href="#webui-根目录" aria-label="Permalink to &quot;WebUI 根目录&quot;">​</a></h2><p>Web 资源文件应放置在模块根目录的 <code>webroot</code> 子目录中，并且其中<strong>必须</strong>有一个名为<code>index.html</code>的文件，该文件是模块页面入口。包含 Web 界面的最简单的模块结构如下：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❯ tree .</span></span>
<span class="line"><span>.</span></span>
<span class="line"><span>|-- module.prop</span></span>
<span class="line"><span>\`-- webroot</span></span>
<span class="line"><span>     \`--index.html</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>安装模块时，KernelSU 会自动设置 <code>webroot</code> 目录的权限和 SELinux context，如果您不知道自己在做什么，请不要自行设置该目录的权限！</p></div><p>如果您的页面包含 CSS 和 JavaScript，您也需要将其放入此目录中。</p><h2 id="javascript-api" tabindex="-1">JavaScript API <a class="header-anchor" href="#javascript-api" aria-label="Permalink to &quot;JavaScript API&quot;">​</a></h2><p>如果只是一个显示页面，那它和普通网页没有什么区别。更重要的是，KernelSU 提供了一系列的系统 API，可以让您实现模块特有的功能。</p><p>KernelSU 提供了一个 JavaScript 库并<a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">在 npm 上发布</a>，您可以在网页的 JavaScript 代码中使用它。</p><p>例如，您可以执行 shell 命令来获取特定配置或修改属性：</p><div class="language-JavaScript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">JavaScript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { exec } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;kernelsu&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">errno</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">stdout</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> exec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;getprop ro.product.model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>再比如，你可以让网页全屏显示，或者显示一个 Toast。</p><p><a href="https://www.npmjs.com/package/kernelsu" target="_blank" rel="noreferrer">API 文档</a></p><p>如果您发现现有的 API 不能满足您的需求或者使用不方便，欢迎<a href="https://github.com/tiann/KernelSU/issues" target="_blank" rel="noreferrer">在这里</a>给我们提出建议！</p><h2 id="一些技巧" tabindex="-1">一些技巧 <a class="header-anchor" href="#一些技巧" aria-label="Permalink to &quot;一些技巧&quot;">​</a></h2><ol><li>您可以正常使用<code>localStorage</code>存储一些数据，但卸载管理器后，这些数据将会丢失。 如果需要持久保存，可以自己将数据写入某个目录。</li><li>对于简单的页面，我建议您使用 <a href="https://parceljs.org/" target="_blank" rel="noreferrer">parceljs</a> 进行打包。它零配置，使用非常方便。不过，如果你是前端高手或者有自己的喜好，那就选择你喜欢的吧！</li></ol>`,18)])])}const u=s(n,[["render",p]]);export{k as __pageData,u as default};
